 if(step.mode==='page')return web.executeJavaScript(`(()=>{const b=document.querySelectorAll('.network-quickbar .game-quick-page')[${Math.floor(index/12)}];b.click();return{page:true};})()`);
 if(step.mode==='menuChoice'){const slot=Number(step.slot??0);if(!Number.isInteger(slot)||slot<0||slot>7)throw new Error('Invalid probe radial slot');return web.executeJavaScript(`(()=>{const b=${step.label?`[...document.querySelectorAll('.radial-overlay:not([hidden]) .radial-entry')].find(n=>n.getAttribute('aria-label')===${JSON.stringify(step.label)})`:`document.querySelector('.radial-overlay:not([hidden]) [data-slot="${slot}"]')`};if(!b||b.disabled)throw new Error('Quickbar radial choice unavailable');b.click();return{chosen:b.getAttribute('aria-label')};})()`);}
 if(step.mode==='inventoryDrop')return web.executeJavaScript(`(()=>{const source=document.querySelectorAll('.network-backpack .network-item')[${Number(step.itemIndex??0)}],target=document.querySelector('.network-quickbar [data-quickbar-index="${index}"]');if(!source||!target)throw new Error('Quickbar inventory drop unavailable');const data=new DataTransfer();source.dispatchEvent(new DragEvent('dragstart',{dataTransfer:data,bubbles:true}));target.dispatchEvent(new DragEvent('drop',{dataTransfer:data,bubbles:true,cancelable:true}));return{itemId:Number(source.dataset.objectId),dropped:true};})()`);
 if(step.mode==='inventoryPowerDrop')return web.executeJavaScript(`(async()=>{const item=document.querySelectorAll('.network-backpack .network-item')[${Number(step.itemIndex??0)}];if(!item)throw new Error('Item power source unavailable');item.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:650,clientY:400}));const selector='.radial-overlay:not([hidden]) [data-slot="${Number(step.slot??3)}"]',deadline=Date.now()+5000;let source;while(!(source=document.querySelector(selector))){if(Date.now()>deadline)throw new Error('Item power entry unavailable');await new Promise(r=>setTimeout(r,25));}const target=document.querySelector('.network-quickbar [data-quickbar-index="${index}"]');if(!source.draggable||!target)throw new Error('Item power drag target unavailable');const data=new DataTransfer();source.dispatchEvent(new DragEvent('dragstart',{dataTransfer:data,bubbles:true}));target.dispatchEvent(new DragEvent('drop',{dataTransfer:data,bubbles:true,cancelable:true}));source.dispatchEvent(new DragEvent('dragend',{dataTransfer:data,bubbles:true}));return{itemId:Number(item.dataset.objectId),powerDropped:true};})()`);
 if(step.mode==='drag'){const source=Number(step.sourceIndex);if(!Number.isInteger(source)||source<0||source>=36)throw new Error('Invalid probe drag source');return web.executeJavaScript(`(()=>{const source=document.querySelector('.network-quickbar [data-quickbar-index="${source}"]'),target=document.querySelector('.network-quickbar [data-quickbar-index="${index}"]');if(!source||!target)throw new Error('Quickbar drag unavailable');const data=new DataTransfer();source.dispatchEvent(new DragEvent('dragstart',{dataTransfer:data,bubbles:true}));target.dispatchEvent(new DragEvent('drop',{dataTransfer:data,bubbles:true,cancelable:true}));return{dropped:true};})()`);}
 if(!['click','context'].includes(step.mode))throw new Error('Invalid probe quickbar action');return web.executeJavaScript(`(()=>{const b=document.querySelector('.network-quickbar [data-quickbar-index="${index}"]');if(!b||b.disabled)throw new Error('Quickbar button unavailable');${step.mode==='click'?'b.click()':"b.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:650,clientY:400}))"};return{dispatched:true};})()`);
